import{z as l,x as s,o as e,c as p,q as n,j as A,D as E,d as r,s as t,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"年金之谜","description":"","frontmatter":{"title":"年金之谜","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/annuity-puzzle.md","filePath":"econ/annuity-puzzle.md","lastUpdated":1791413859000}'),d={name:"econ/annuity-puzzle.md"};function D(m,a,C,u,f,h){const i=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=n('<h1 id="年金之谜" tabindex="-1">年金之谜 <a class="header-anchor" href="#年金之谜" aria-label="Permalink to &quot;年金之谜&quot;">​</a></h1><div class="epigraph"><p>公平年金把长寿风险从个人挪到池里；理论说退休者应把大部分财富年金化，市场里他们几乎不买。</p><footer>—— Yaari, Uncertain Lifetime, Life Insurance, and the Theory of the Consumer, RES 1965；Davidoff, Brown and Diamond, AER 2005</footer></div><p><a href="/econ/bequest-motive">上一课</a>留下终点财富的两种读法。本课缺口是保险市场：Yaari（1965）证明，无遗赠动机且年金精算公平时，最优是把财富全部年金化——活着就有支付，死后无残值，正好对冲寿命。自愿年金需求远低于这一基准，是谜。不重写 \\(v(b)\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>确定寿命下 LCH 不需要年金。寿命随机时，自保要求多留缓冲，死后留下意外遗产。精算公平的终身年金按存活概率支付，欧拉里出现「活着才有下一期」的项，最优持有把非年金财富压到零（Yaari）。Mitchell、Poterba、Warshawsky 与 Brown 以及后续文献记录：私人年金市场规模小，加载（费用、逆选择）高，但即使用加载校正，需求仍低。Davidoff、Brown 与 Diamond（2005）在更一般的偏好与不完全年金菜单下仍得到：应年金化的份额远高于观测。</p><p>缺口是在遗赠与市场摩擦之间定位谜，而不是重讲预防性储蓄。</p><p><span class="marginnote">逆选择：长寿者更买年金，推高价格，短寿者退出。这能解释加载，难以单独解释接近零的自愿需求。</span></p><p><span class="marginnote">「精算公平」是保险定价的理论基准线：保费恰好等于按存活概率算出的期望赔付，保险公司平均不赚不赔。现实报价还要加「加载」——比如每 1 元期望赔付收 1.15 元保费，多出的 0.15 元覆盖销售费用、准备金和逆选择带来的超额赔付。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 Yaari 基准上逐项放松：有意遗赠给出残值需求；年金相对债券的加载；医疗与长期护理的不可保支出（年金支付在生病时不够灵活）；家族内部风险分担；现时偏差与金融素养使人低估长寿或拖延购买。本课把菜单列清，不把住房与组合之谜提前写完——住房常常充当劣质年金（住着就消费、卖掉才有残值）。</p>',10)),(e(),A(o,null,{default:E(()=>[t(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22Yaari%3A%20%E5%85%AC%E5%B9%B3%E5%B9%B4%E9%87%91%E5%BA%94%E5%90%83%E6%8E%89%E8%B4%A2%E5%AF%8C%22%5D%20--%3E%20GAP%5B%22%E8%87%AA%E6%84%BF%E9%9C%80%E6%B1%82%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20GAP%20--%3E%20BEQ%5B%22%E6%9C%89%E6%84%8F%E9%81%97%E8%B5%A0%E8%A6%81%E6%AE%8B%E5%80%BC%22%5D%0A%20%20GAP%20--%3E%20LOAD%5B%22%E5%8A%A0%E8%BD%BD%E4%B8%8E%E9%80%86%E9%80%89%E6%8B%A9%22%5D%0A%20%20GAP%20--%3E%20RISK%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%9D%E6%94%AF%E5%87%BA%E8%A6%81%E6%B5%81%E5%8A%A8%22%5D%0A%20%20GAP%20--%3E%20BEH%5B%22%E6%8B%96%E5%BB%B6%E3%80%81%E7%B4%A0%E5%85%BB%E3%80%81%E7%8E%B0%E6%97%B6%E5%81%8F%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"年金的机制是条件支付：只有存活状态才给钱，等价于按存活概率提高有效回报。这正是长寿保险。谜是为何家庭拒绝这个更高的条件回报。若 \\(v(b)\\gt 0\\)，拒绝可以是理性的。若 \\(v\\approx 0\\) 仍拒绝，则要么加载过大，要么偏好或信念偏离 Yaari：例如对长寿概率加权不足，或把年金看成「赌自己死得早」。后一类已经踩进前景理论的损失框架，本单元先记账，行为单元再展开。",-1)),a[5]||(a[5]=B("p",null,"第一张图问的是「人们为何不买」；这一张换个问题：同样一笔钱，买债券和买年金在两种状态下各是什么结果——溢价与代价分别出现在哪一格。",-1)),(e(),A(o,null,{default:E(()=>[t(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E9%80%80%E4%BC%91%E6%97%B6%E5%90%8C%E6%A0%B7%E4%B8%80%E7%AC%94%E8%B4%A2%E5%AF%8C%22%5D%20--%3E%20B%5B%22%E5%85%A8%E4%B9%B0%E5%80%BA%E5%88%B8%22%5D%0A%20%20W%20--%3E%20A%5B%22%E5%85%A8%E4%B9%B0%E5%B9%B4%E9%87%91%22%5D%0A%20%20B%20--%3E%20S1%5B%22%E6%B4%BB%E7%9D%80%EF%BC%9A%E5%8F%AA%E6%9C%89%E5%88%A9%E6%81%AF%E5%8F%AF%E8%8A%B1%EF%BC%8C%E6%9C%AC%E9%87%91%E4%B8%8D%E6%95%A2%E5%8A%A8%22%5D%0A%20%20B%20--%3E%20D1%5B%22%E5%8E%BB%E4%B8%96%EF%BC%9A%E6%9C%AC%E9%87%91%E5%AE%8C%E5%A5%BD%EF%BC%8C%E7%95%99%E7%BB%99%E7%BB%A7%E6%89%BF%E4%BA%BA%22%5D%0A%20%20A%20--%3E%20S2%5B%22%E6%B4%BB%E7%9D%80%EF%BC%9A%E6%AF%8F%E6%9C%9F%E9%A2%86%E5%BE%97%E6%9B%B4%E5%A4%9A%EF%BC%8C%E5%90%AB%E5%AD%98%E6%B4%BB%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20A%20--%3E%20D2%5B%22%E5%8E%BB%E4%B8%96%EF%BC%9A%E5%81%9C%E4%BB%98%EF%BC%8C%E6%B2%A1%E6%9C%89%E6%AE%8B%E5%80%BC%22%5D%0A%20%20S2%20--%3E%20Q%5B%22%E6%8B%92%E7%BB%9D%E5%B9%B4%E9%87%91%20%3D%20%E6%94%BE%E5%BC%83%20S2%20%E7%9A%84%E6%BA%A2%E4%BB%B7%E5%8E%BB%E4%BF%9D%20D1%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p>不把年金报价写成限价簿。精算价格是合同，不是盘口。量化栏若遇到年金二级市场，那是产品微观结构，本课只问家庭为什么不买一级合同。</p><p>Yaari 的欧拉多了一项存活概率：活着才需要下一期消费，年金把「死了就停付」写进回报，有效 \\(r\\) 高于债券。拒绝年金等于拒绝这笔条件超额。加载可以把超额吃掉；Davidoff–Brown–Diamond 的要点是：合理加载仍留下应买而未买的份额。行为解释（把年金当赌命）先记账，前景理论课再给 \\(v\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>公共养老金与职业年金已经强制年金化了一块财富，自愿市场小可能是替代而不是谜。本课承认替代，仍留下私人财富中可年金化而未年金化的部分。也不估计最优份额。</p><p>后课默认：住房同时提供消费服务与部分长寿对冲，会进一步挤出金融年金——下一课写这个资产。</p><p>Yaari 的条件回报来自「死了就停付」；拒绝年金等于拒绝这笔存活溢价。</p><p><span class="marginnote">数字实例：若明年存活概率 \\(p=0.95\\)，公平年金因为「死了就停付」，隐含有效回报比同期限无风险债券高约 \\(1/0.95-1\\approx 5.3\\%\\)。这 5.3 个百分点不是额外收益，是用「早走一步的人拿不回本金」换来的条件补偿。</span></p><p>公共养老金已强制年金化一块，谜留下的是私人财富中可买而未买的份额。</p><p><span class="marginnote">直觉类比：年金像和一群同龄人合伙管理一个池子——每人出一笔钱，还活着的每年分钱，先离场的自动退出、不再领取。它不是赌自己死得早，而是把「活太久、钱花光」这个风险转嫁给池子；参保的人越多、寿命波动越能互相抵消，池子就越好。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Yaari：无遗赠、公平年金时，财富应全部年金化。</li><li>观测需求远低：遗赠、加载、不可保支出与行为都能贡献。</li><li>与意外遗赠同一枚硬币：不买年金，死后才有残值。</li><li>有意遗赠要残值，与纯意外遗赠的符号相反。</li><li>把年金当赌命是后课前景理论的记账。</li><li>出处：Yaari, <em>RES</em> 1965；Davidoff, Brown and Diamond, <em>AER</em> 2005。</li></ul>',11))])}const _=l(d,[["render",D]]);export{F as __pageData,_ as default};
